import{_ as t,a as r,c as a,ac as o}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"Kubernetes权威指南（第4版）","description":"按2019年第4版12章整理 Kubernetes 的运行机制、网络、存储、安全与运维。","frontmatter":{"title":"Kubernetes权威指南（第4版）","description":"按2019年第4版12章整理 Kubernetes 的运行机制、网络、存储、安全与运维。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单 · 计算机与软件工程 · 架构、运维与云原生","summary":"按2019年第4版12章整理 Kubernetes 的运行机制、网络、存储、安全与运维。","status":"active","related":[{"title":"云原生服务网格Istio","link":"/life/personal/books/computing/istio","kind":"书籍导读","scope":"general","audience":"general"}],"prev":{"text":"云原生服务网格Istio","link":"/life/personal/books/computing/istio"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"云原生服务网格Istio","link":"/life/personal/books/computing/istio"},"next":false},"headers":[],"relativePath":"life/personal/books/computing/kubernetes-guide.md","filePath":"life/personal/books/computing/kubernetes-guide.md"}'),n={name:"life/personal/books/computing/kubernetes-guide.md"};function i(s,e,d,l,u,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="kubernetes权威指南-第4版" tabindex="-1">Kubernetes权威指南（第4版） <a class="header-anchor" href="#kubernetes权威指南-第4版" aria-label="Permalink to &quot;Kubernetes权威指南（第4版）&quot;">​</a></h1><p><a href="./../overview">返回分类书单</a></p><p><strong>分类：计算机与软件工程 / 架构、运维与云原生</strong></p><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p>这本书在书单中承担容器编排与集群管理的系统学习任务，适合已经接触容器、希望理解应用如何在集群中部署和运行的读者。核心问题是：如何描述期望状态，系统怎样持续接近它，偏离时又如何排查。</p><p>可以选择一个小型服务贯穿阅读：从容器、工作负载和服务暴露，到配置、数据持久化、滚动升级与故障恢复，每一步都检查对应的集群对象和状态。</p><h2 id="版本说明" tabindex="-1">版本说明 <a class="header-anchor" href="#版本说明" aria-label="Permalink to &quot;版本说明&quot;">​</a></h2><p>本页对应龚正、吴治辉、崔秀龙、闫健勇著，电子工业出版社 <strong>2019 年第4版</strong>，完整书名为《Kubernetes权威指南：从Docker到Kubernetes实践全接触（第4版）》，ISBN <strong>9787121362354</strong>。公开书目说明覆盖 Kubernetes 1.0 至 1.14 的主要特性，下表据该版目录整理 12 章；尚未直接复核出版社完整目录。旧版 API、网络插件和运行时配置必须与书中环境对应，不能直接套用于当前集群。</p><h2 id="作者与背景" tabindex="-1">作者与背景 <a class="header-anchor" href="#作者与背景" aria-label="Permalink to &quot;作者与背景&quot;">​</a></h2><p>作者为龚正、吴治辉、崔秀龙、闫健勇，采用本页列出的第4版书目。其内容定位是面向集群使用、开发与运维的综合实践指南；“权威指南”是书名，不代表 Kubernetes 项目的官方规范。本次未取得可独立核实四人完整履历的出版社原始介绍，因此不补写现任职务或社区头衔。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>适合有容器与 Linux 基础、需要系统掌握集群对象及排障路径的开发者和运维人员。只想发布单个应用者可以先读入门、Pod、Service；平台维护者再进入网络、存储、安全与核心组件。</p><h2 id="章节介绍" tabindex="-1">章节介绍 <a class="header-anchor" href="#章节介绍" aria-label="Permalink to &quot;章节介绍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>阅读与验证重点</th></tr></thead><tbody><tr><td>第1章 Kubernetes 入门</td><td>从架构与基本对象建立集群全貌，将容器应用放入编排系统中理解。</td></tr><tr><td>第2章 Kubernetes 安装配置指南</td><td>介绍书中环境的搭建与组件配置，明确节点和控制组件的依赖。</td></tr><tr><td>第3章 深入掌握 Pod</td><td>研究工作负载的配置、生命周期与管理方式，观察期望状态如何落实。</td></tr><tr><td>第4章 深入掌握 Service</td><td>理解服务发现与访问入口，追踪服务抽象到实际后端的流量。</td></tr><tr><td>第5章 核心组件运行机制</td><td>分析核心组件之间的协作，区分状态保存、调度与持续协调。</td></tr><tr><td>第6章 深入分析集群安全机制</td><td>讨论身份、权限和访问边界，理解安全控制作用于哪个层次。</td></tr><tr><td>第7章 网络原理</td><td>解释容器与节点间通信、网络方案及相关排障方法。</td></tr><tr><td>第8章 共享存储原理</td><td>将卷、存储实现和应用需求关联，关注重调度后的数据可达性。</td></tr><tr><td>第9章 Kubernetes 开发指南</td><td>认识面向 Kubernetes 的开发与扩展方式，理解与 API 交互的边界。</td></tr><tr><td>第10章 Kubernetes 集群管理</td><td>汇集运行维护、资源与集群管理实践，强调配置变化后的验证。</td></tr><tr><td>第11章 Trouble Shooting 指导</td><td>通过对象、事件、日志和组件状态缩小故障范围。</td></tr><tr><td>第12章 Kubernetes 开发中的新功能</td><td>介绍成书时正在演进的功能；其当时状态不能代表当前支持情况。</td></tr></tbody></table><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><p>以下为本站阅读评析，用可实践的阅读目标表达收获，不代表书单提供者已经读完、任职或完成相应项目。版本未明时，评析只针对本页明确标注的主题或参考版本。</p><h3 id="金句摘抄或阅读提炼" tabindex="-1">金句摘抄或阅读提炼 <a class="header-anchor" href="#金句摘抄或阅读提炼" aria-label="Permalink to &quot;金句摘抄或阅读提炼&quot;">​</a></h3><blockquote><p>声明期望状态以后，还要追踪控制循环给出的实际状态。</p></blockquote><p>这是本站原创阅读提炼，不是原书引文；没有可核对页码的原文不作逐字摘抄。</p><h3 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to &quot;个人收获&quot;">​</a></h3><p>用一个小服务串起配置提交、调度、拉取镜像、就绪和服务访问，遇到失败时分别查看对象状态、事件与日志。能够说明卡在哪一阶段，才是从会写 YAML 进步到理解平台。</p><h3 id="客观评价与阅读建议" tabindex="-1">客观评价与阅读建议 <a class="header-anchor" href="#客观评价与阅读建议" aria-label="Permalink to &quot;客观评价与阅读建议&quot;">​</a></h3><p>覆盖面广使它适合建立地图，也意味着单个主题的深入程度有限。第4版面向旧 API 与运行环境，阅读时应把架构原理和操作清单分开；迁移到新集群须逐项核对 API 废弃、插件与安全默认值。</p><p><strong>推荐语（本站原创，非原书引用）：</strong> 推荐作为 Kubernetes 机制的路线图：带一个服务读完整条生命周期，再按真实问题回查专题。</p><h2 id="来源与核对入口" tabindex="-1">来源与核对入口 <a class="header-anchor" href="#来源与核对入口" aria-label="Permalink to &quot;来源与核对入口&quot;">​</a></h2><ul><li><a href="https://book.douban.com/subject/33444476/" target="_blank" rel="noopener noreferrer">第4版中文书目与完整目录</a>：作者、ISBN、版本范围与 12 章结构的核对来源。</li><li><a href="https://www.broadview.com.cn/" target="_blank" rel="noopener noreferrer">博文视点</a>：出版品牌的版本与配套资料核对入口；本次未取得该书完整出版社目录。</li><li><a href="https://kubernetes.io/zh-cn/docs/concepts/" target="_blank" rel="noopener noreferrer">Kubernetes 官方概念文档</a>：当前概念的补充参考，不是原书目录来源。</li><li><a href="https://kubernetes.io/docs/reference/using-api/deprecation-guide/" target="_blank" rel="noopener noreferrer">Kubernetes 废弃 API 迁移指南</a>：将旧版案例迁移到当前集群时核对兼容性。</li></ul>',26)])])}const c=t(n,[["render",i]]);export{p as __pageData,c as default};
